css:
.title h2 {
    font-weight: Bold;
    font-size: 25px;
}
.info-invoice td, .info-invoice th, .info-invoice .info-helper {
    padding: 6px 0.3rem !important;
 }
.table-info .table th, .table-info .table td {
    border: 0;
    padding: 1px .3rem !important;
}
.table-info .table th, .table-invoice-amount th {
    text-align: left;
}
.table-info .table td, .table-invoice-amount td  {
    text-align: right;
}

.table-invoice-amount {
  margin-top: 20px;
}
.table-invoice-amount table {
  width: 100%;
  border-collapse: collapse;
}
.table-invoice-amount th, .table-invoice-amount td {
  border: 0;

  vertical-align: top;
}

.table-invoice-amount .price-header {
    text-align: right;
  font-weight: bold;
  font-size: 14px;
}
.table-invoice-amount .price-value {

}
.table-invoice-amount tr.total {
    background-color: var(--yellow-300);
}

.qr-bill {
    position: relative;
    display: flex;
    width: 100%;
    border-top: 2px dashed #0000006e;
    border-top-width: 2px;
    page-break-after: always;
    margin-top: auto;
}
.qr-bill.cut-line::before {
    content: "";
    position: absolute;
    right: 10%; /* adjust to sit on the edge */
    top: -11px;
    width: 20px;
    height: 20px;
    background: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="none" viewBox="0 0 24 24"><path d="M9 18.5L17 3M9 18.5C9 19.8807 7.88071 21 6.5 21C5.11929 21 4 19.8807 4 18.5C4 17.1193 5.11929 16 6.5 16C7.88071 16 9 17.1193 9 18.5ZM15 18.5L7 3M15 18.5C15 19.8807 16.1193 21 17.5 21C18.8807 21 20 19.8807 20 18.5C20 17.1193 18.8807 16 17.5 16C16.1193 16 15 17.1193 15 18.5Z" stroke="%23000" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>');
    background-size: contain;
    transform: rotate(-90deg);
}
.qr-bill .receipt {
    border-right: 2px dashed #0000006e;
    border-right-width: 2px;
}
.qr-bill .receipt.cut-line::before {
    content: "";
    position: absolute;
    right: -11px; /* adjust to sit on the edge */
    bottom: 11%;
    width: 20px;
    height: 20px;
    background: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="none" viewBox="0 0 24 24"><path d="M9 18.5L17 3M9 18.5C9 19.8807 7.88071 21 6.5 21C5.11929 21 4 19.8807 4 18.5C4 17.1193 5.11929 16 6.5 16C7.88071 16 9 17.1193 9 18.5ZM15 18.5L7 3M15 18.5C15 19.8807 16.1193 21 17.5 21C18.8807 21 20 19.8807 20 18.5C20 17.1193 18.8807 16 17.5 16C16.1193 16 15 17.1193 15 18.5Z" stroke="%23000" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>');
    background-size: contain;
}
.qr-bill h6 {
    font-size: 14px;
}

.qr-bill p {
    font-size: smaller;
    margin-bottom: 0.4rem;
}

.qr-bill .qr-code-img {
    background: #fff;
    max-width: 100%;
}

.valute {
    display: flex;
    gap: 20%;
}
@media print {
  .qr-bill {
    margin-top: auto;
    bottom: 0;
    left: 0;
    width: 100%;
    padding: 10px;
    font-size: 14px;
    background: white; /* optional, ensures text is readable */
  }
}
